'use client';
// Staff PINs. One code for the whole team (default) or a code per staff member. New PINs are generated by the
// server (never a weak one like 1234), shown here once, and stored only as a keyed hash.
import { useState, type FormEvent } from 'react';
import { useDashboard } from '../../../components/Dashboard';
import { Loading, useLoad } from '../../../components/useLoad';
import { businessAdmin, fmtDate, listStaff, type PinMode } from '../../../lib/api';

type Shown = { name: string; pin: string };

export default function TeamPage() {
  const { business, reload: reloadBusiness } = useDashboard();
  const { data: staff, error, loading, reload } = useLoad(() => listStaff(business.id), [business.id, business.pinMode]);
  const [shown, setShown] = useState<Shown | null>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [name, setName] = useState('');

  const run = async (body: Parameters<typeof businessAdmin>[0], confirmText?: string) => {
    if (confirmText && !window.confirm(confirmText)) return;
    setBusy(true);
    setMessage(null);
    try {
      const r = await businessAdmin(body);
      if (r.status === 'pin') setShown({ name: r.name, pin: r.pin });
      else if (r.status !== 'ok') setMessage(r.status === 'forbidden' ? 'אין הרשאה לעסק הזה.' : 'הפעולה לא התאפשרה.');
      if (body.action === 'pin_mode') await reloadBusiness();
      await reload();
    } catch (e) {
      setMessage(`משהו השתבש: ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      setBusy(false);
    }
  };

  const setMode = (mode: PinMode) => {
    if (mode === business.pinMode) return;
    run(
      { action: 'pin_mode', businessId: business.id, mode },
      mode === 'shared'
        ? 'לעבור לקוד אחד לכל הצוות? הקודים האישיים יבוטלו ויווצר קוד צוות חדש.'
        : 'לעבור לקוד לכל עובד/ת? קוד הצוות יבוטל. עד שתוסיפו עובדים, אי אפשר יהיה לאשר חותמות בקופה.',
    );
  };

  const add = (e: FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;
    run({ action: 'staff_add', businessId: business.id, name: name.trim() }).then(() => setName(''));
  };

  return (
    <div className="page">
      <div className="page-head">
        <h1>צוות</h1>
        <p className="muted">בקופה, אחרי שהלקוח סורק, מי שבצוות מקליד קוד בן 4 ספרות על הטלפון של הלקוח. רק אז נרשמת החותמת או ממומשת ההטבה.</p>
      </div>

      {shown ? (
        <div className="hero" role="status">
          <span className="small">{shown.name === 'צוות' ? 'קוד הצוות החדש' : `הקוד החדש של ${shown.name}`}</span>
          <span className="pin">{shown.pin}</span>
          <p>הקוד מוצג רק עכשיו ולא יוצג שוב. מעבירים אותו בעל פה, לא בצילום מסך.</p>
          <div><button className="btn" onClick={() => setShown(null)}>רשמתי, סגירה</button></div>
        </div>
      ) : null}

      <div className="card">
        <h3>איך הצוות מאשר</h3>
        <div className="seg" role="group" aria-label="מצב הקודים">
          <button aria-pressed={business.pinMode === 'shared'} onClick={() => setMode('shared')} disabled={busy}>קוד אחד לכל הצוות</button>
          <button aria-pressed={business.pinMode === 'per_staff'} onClick={() => setMode('per_staff')} disabled={busy}>קוד לכל עובד/ת</button>
        </div>
        <p className="muted small">
          {business.pinMode === 'shared'
            ? 'פשוט להתחלה. ביומן כל פעולה תירשם כ״צוות״.'
            : 'כל אחד עם קוד משלו: ביומן רואים מי אישר כל חותמת והטבה, ואפשר לבטל קוד של מי שעזב בלי להחליף לכולם.'}
        </p>
      </div>

      {message ? <p className="note" role="alert">{message}</p> : null}
      {loading && !staff ? <Loading onRetry={reload} /> : error ? <Loading error={error} onRetry={reload} /> : null}

      {staff && business.pinMode === 'shared' ? (
        <div className="card">
          <h3>קוד הצוות</h3>
          {staff.length ? (
            <p>פעיל מאז {fmtDate(staff[0].createdAt)}.</p>
          ) : (
            <p className="note warn">אין קוד צוות פעיל, ולכן אי אפשר לאשר חותמות והטבות בקופה. צרו קוד.</p>
          )}
          <p className="muted small">הקוד מוקלד על הטלפון של הלקוח, ולקוח שמסתכל יכול ללמוד אותו. מומלץ להחליף אותו מדי פעם, ומיד אם מישהו עזב.</p>
          <div>
            <button className="btn" disabled={busy} onClick={() => run({ action: 'team_pin', businessId: business.id }, staff.length ? 'להחליף את קוד הצוות? הקוד הנוכחי יפסיק לעבוד מיד.' : undefined)}>
              {staff.length ? 'החלפת הקוד' : 'יצירת קוד צוות'}
            </button>
          </div>
        </div>
      ) : null}

      {staff && business.pinMode === 'per_staff' ? (
        <>
          {staff.length === 0 ? <p className="note warn">אין עובדים עם קוד, ולכן אי אפשר לאשר חותמות והטבות בקופה. הוסיפו את הצוות.</p> : null}
          <ul className="list" aria-label="עובדים">
            {staff.map((s) => (
              <li key={s.id}>
                <div className="grow">
                  <strong>{s.name}</strong>
                  <div className="muted small">קוד מאז {fmtDate(s.createdAt)}</div>
                </div>
                <button className="btn small quiet" disabled={busy} onClick={() => run({ action: 'pin_reset', businessId: business.id, staffPinId: s.id }, `ליצור ל${s.name} קוד חדש? הקוד הנוכחי יפסיק לעבוד.`)}>קוד חדש</button>
                <button className="btn small quiet" disabled={busy} onClick={() => run({ action: 'staff_remove', businessId: business.id, staffPinId: s.id }, `להסיר את ${s.name}? הקוד יפסיק לעבוד. הפעולות שלו נשארות ביומן.`)}>הסרה</button>
              </li>
            ))}
          </ul>
          <form className="card" onSubmit={add}>
            <h3>הוספת עובד/ת</h3>
            <label className="field">
              שם
              <span className="hint">כפי שיופיע ביומן. הקוד נוצר אוטומטית ומוצג פעם אחת.</span>
              <input value={name} onChange={(e) => setName(e.target.value)} maxLength={40} />
            </label>
            <div><button className="btn" disabled={busy || !name.trim()}>הוספה ויצירת קוד</button></div>
          </form>
        </>
      ) : null}
    </div>
  );
}
